head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


/**
 * 일괄로직점검 팝업창 
 */
/**
 * @method
 * @name fn_OpenLogicCheck
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenLogicCheck = async function() {
    await $c.frame.CreateDialogFrame("LOSSLMT_ETNLOGIGCHK", "/etn/ULDSTF08131.gfm", "ETN 일괄로직점검(손실제한)", 200, 100, 770, 450, "window");
};


/********************************************** 
 * 함수명 : fn_recv_acpt()
 * 설명   : ETN 접수처리
 *          ULDSTF080002 ~ 5.gfm 화면에 공통사용
 **********************************************/
/**
 * @method
 * @name fn_recv_acpt
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_recv_acpt = function() {
    procJob = "승인처리 ";
    var res = window.confirm(procJob + "하시겠습니까?");
    if (res) {
        dts_Isu.setCellData(1, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_10);
        scwin.fn_recv_trs();
    }
};



/********************************************** 
 * 함수명 : fn_recv_ret()
 * 설명   : ETN 반송처리
 *          ULDSTF080002 ~ 5.gfm 화면에 공통사용
 **********************************************/
/**
 * @method
 * @name fn_recv_ret
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_recv_ret = function() {
    procJob = "승인거부처리 ";
    var res = window.confirm(procJob + "하시겠습니까?");
    if (res) {
        dts_Isu.setCellData(1, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_02);
        scwin.fn_recv_trs();
    }
};




/********************************************** 
 * 함수명 : fn_recvret_trs()
 * 설명   : ETN 반송처리
 *          ULDSTF080002 ~ 5.gfm 화면에 공통사용
 **********************************************/
/**
 * @method
 * @name fn_recv_trs
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_recv_trs = function() {
    trs_Save.Action = $c.lce.fn_encodeNSession("/digital/DigitalListedRcv.do?method=receiveDigitalAcptRet&SCREN_ID=" + vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Post();
};




/********************************************** 
 * 함수명 : fn_RetRsn_Search()
 * 설명   : ETN 반송사유 조회
 **********************************************/
/**
 * @method
 * @name fn_RetRsn_Search
 * @description desc
 * @param {string} paramBzProcsNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RetRsn_Search = function(paramBzProcsNo) {
    var url = "/etn/EtnListedRcv.do";
    url += "?method=readRecvEtnRetRsn";
    url += "&SCREN_ID=" + vScrenID;
    url += "&outputMessageId=ETN_LISTEDRCV_RESRSN_SEARCH_OUT";
    url += "&SCREN_ID=" + fr_SecuGrpId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&BZ_PROCS_NO=" + paramBzProcsNo;
    dts_RetRsn.DataID = encodeURI(url);
    dts_RetRsn.Reset();
    txb_RET_RSN.setValue(dts_RetRsn.getCellData(1, "RET_RSN"));
};



/********************************************** 
 * 함수명 : fn_SetRetTypeCombo()
 * 설명   : ETN심사청구반송구분코드 조회
 **********************************************/
/**
* @method

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

 * @name X
 * @description desc
 * @param {string} dtsObj desc
* @returns
* @hidden N
* @exception
* @example
*/

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.X = function(dtsObj) {
    var url = "/CodeAction.do?method=listCodeValueName";
    url += "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT";
    url += "&SCREN_ID=" + fr_SecuGrpId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ENG_NM=ETN_INVSTG_CLM_RET_TP_CD";
    url += "&For=R";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};


/**
 * 종목상세정보 팝업창
 */
/**
 * @method
 * @name fn_OpenDetailRecv
 * @description desc
 * @param {string} vbzTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailRecv = async function(vbzTpCd) {
    var screenId = "";
    var screenNm = "";
    if (vbzTpCd == LIST_BZ_TP_CD_780) {
        screenId = "ULDSTF70006";
        screenNm = "DIGITAL 상장예비심사";
    } else if (vbzTpCd == LIST_BZ_TP_CD_781) {
        screenId = "ULDSTF70007";
        screenNm = "DIGITAL 신규상장";
    } else if (vbzTpCd == LIST_BZ_TP_CD_783) {
        screenId = "ULDSTF70008";
        screenNm = "DIGITAL 추가상장예비심사";
    } else if (vbzTpCd == LIST_BZ_TP_CD_784) {
        screenId = "ULDSTF70009";
        screenNm = "DIGITAL 추가상장";
    }
    await $c.frame.CreateDialogFrame("DLG_ETNRECV", "/digital/" + screenId + ".gfm", screenNm, 10, -50, 1104, 920, "window");
};


/**
 * DIGITAL 일치여부 팝업창
 */
/**
 * @method
 * @name fn_OpenCorrYn
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenCorrYn = async function() {
    await $c.frame.CreateDialogFrame("DLG_ETNCORRYN", "/digital/ULDSTF70007P.gfm", "디지털증권 일치여부확인", 100, 10, 785, 800, "window");
};
rptType_01 = '01'; //신규상장 심사청구
rptType_02 = '02'; //신규상장 상장신청
rptType_03 = '03'; //추가상장 심사청구
rptType_04 = '04'; //추가상장 상장신청

rptFileNm_01 = 'RLDSTF70006'; //신규상장 심사청구
rptFileNm_02 = 'RLDSTF70007'; //신규상장 상장신청
rptFileNm_03 = 'RLDSTF70008'; //추가상장 심사청구
rptFileNm_04 = 'RLDSTF70009'; //추가상장 상장신


rpt_Header = "";
rptFileNm = "";

/**
 * 신규심사/상장, 추가심사/상장 구분
 * @param rptType
 */
/**
 * @method
 * @name fn_getEtnIsuQty
 * @description desc
 * @param {string} rptType desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getEtnIsuQty = function(rptType) {
    if (rptType == scwin.rptType_01) {
        scwin.rpt_Header = "상장예비심사";
        scwin.rptFileNm = scwin.rptFileNm_01;
    } else if (rptType == scwin.rptType_02) {
        scwin.rpt_Header = "신규상장";
        scwin.rptFileNm = scwin.rptFileNm_02;
    } else if (rptType == scwin.rptType_03) {
        scwin.rpt_Header = "추가상장예비심사";
        scwin.rptFileNm = scwin.rptFileNm_03;
    } else if (rptType == scwin.rptType_04) {
        scwin.rpt_Header = "추가상장";
        scwin.rptFileNm = scwin.rptFileNm_04;
    }
};



